// Body builder shared by .github/workflows/auto-pr-staging.yml (master -> staging)
// and .github/workflows/auto-pr-stable.yml (staging -> stable).

const { execFileSync } = require("child_process");

const MAX_LISTED = 100;

// Bot commits; the PR they reference is already captured by its own merge commit.
const EXCLUDE_SUBJECT = [
  /^Update changelog for PR\b/i,
  /^chore: automatically update REUSE headers\b/i,
];

// The promotion PRs themselves, which land in the next promotion's delta.
const AUTO_SYNC_TITLE = /^Auto: sync\b/i;

function git(args) {
  return execFileSync("git", args, { encoding: "utf8", maxBuffer: 64 * 1024 * 1024 });
}

module.exports = async function promotionOverview({ github, context, core, base, head, labels }) {
  const { owner, repo } = context.repo;
  const today = new Date().toISOString().slice(0, 10).split("-").reverse().join("-");

  git(["fetch", "--no-tags", "--quiet", "origin",
    `+refs/heads/${base}:refs/remotes/origin/${base}`,
    `+refs/heads/${head}:refs/remotes/origin/${head}`]);

  const range = `origin/${base}..origin/${head}`;
  const totalCommits = Number(git(["rev-list", "--count", range]).trim());
  if (totalCommits === 0) {
    core.info(`No delta between ${head} and ${base} — nothing to propose.`);
    return;
  }

  // First parents only. Following every parent walks into merges, so an upstream
  // merge drags in every space-station-14 commit since the last sync, each with a
  // "(#NNN)" subject that means nothing here.
  const landed = git(["log", "--first-parent", "--format=%H%x1f%s%x1e", range])
    .split("\x1e")
    .map((record) => record.trim())
    .filter(Boolean)
    .map((record) => {
      const [sha, subject] = record.split("\x1f");
      return { sha, subject };
    });

  core.info(`${head} is ${totalCommits} commit(s) ahead of ${base}, ${landed.length} of them landed directly.`);

  // A number that does not resolve here came in from upstream.
  const prCache = new Map();
  async function getPullRequest(number) {
    if (prCache.has(number)) return prCache.get(number);

    let pr = null;
    try {
      const { data } = await github.rest.pulls.get({ owner, repo, pull_number: number });
      pr = data;
    } catch (err) {
      if (err.status !== 404) core.warning(`Could not read PR #${number}: ${err.message}`);
    }

    prCache.set(number, pr);
    return pr;
  }

  const queued = [];
  const seen = new Set();
  const directCommits = [];
  let foreignRefs = 0;

  for (const commit of landed) {
    if (EXCLUDE_SUBJECT.some((re) => re.test(commit.subject))) continue;

    const merge = commit.subject.match(/^Merge pull request #(\d+)\b/);
    const squash = commit.subject.match(/\(#(\d+)\)\s*$/);
    const number = merge ? Number(merge[1]) : squash ? Number(squash[1]) : null;

    if (number === null) {
      directCommits.push(commit);
      continue;
    }

    const pr = await getPullRequest(number);
    if (!pr) {
      foreignRefs++;
      continue;
    }
    if (AUTO_SYNC_TITLE.test(pr.title)) continue;
    if (seen.has(number)) continue;

    seen.add(number);
    queued.push(pr);
  }

  const lines = [
    `Automated pull request keeping **\`${base}\`** in sync with **\`${head}\`**.`,
    "",
    `Generated by the \`Auto PR: ${head} -> ${base}\` workflow on ${today}.`,
    "",
    `\`${head}\` is **${totalCommits}** commit(s) ahead of \`${base}\`, landed in **${landed.length}** merge(s) and direct commit(s).`,
    "",
    "---",
    "",
  ];

  if (queued.length > 0) {
    lines.push(`### Pull requests queued for \`${base}\` (${queued.length})`);
    lines.push("");
    for (const pr of queued.slice(0, MAX_LISTED)) {
      const author = pr.user ? `@${pr.user.login}` : "unknown";
      lines.push(`- [ ] #${pr.number} — ${pr.title} (${author})`);
    }
    if (queued.length > MAX_LISTED) {
      lines.push("");
      lines.push(`…and ${queued.length - MAX_LISTED} more.`);
    }
  } else {
    lines.push(`### Pull requests queued for \`${base}\``);
    lines.push("");
    lines.push("_No PR-associated commits found in the delta._");
  }

  if (directCommits.length > 0) {
    lines.push("");
    lines.push(`<details><summary>Direct commits without an associated PR (${directCommits.length})</summary>`);
    lines.push("");
    for (const commit of directCommits.slice(0, MAX_LISTED)) {
      lines.push(`- ${commit.sha.slice(0, 8)} ${commit.subject}`);
    }
    if (directCommits.length > MAX_LISTED) {
      lines.push("");
      lines.push(`…and ${directCommits.length - MAX_LISTED} more.`);
    }
    lines.push("");
    lines.push("</details>");
  }

  if (foreignRefs > 0) {
    lines.push("");
    lines.push(`_${foreignRefs} commit(s) referenced a pull request that does not exist in this repository (upstream numbering) and were left out._`);
  }

  const body = lines.join("\n");
  const title = `Auto: sync ${head} into ${base} (${today})`;

  const existing = await github.rest.pulls.list({
    owner,
    repo,
    state: "open",
    base,
    head: `${owner}:${head}`,
  });

  if (existing.data.length > 0) {
    const pr = existing.data[0];
    await github.rest.pulls.update({ owner, repo, pull_number: pr.number, title, body });
    core.info(`Refreshed overview on existing PR #${pr.number}: ${pr.html_url}`);
    return;
  }

  let pr;
  try {
    const created = await github.rest.pulls.create({
      owner,
      repo,
      base,
      head,
      title,
      body,
      maintainer_can_modify: true,
    });
    pr = created.data;
  } catch (err) {
    core.warning(`pulls.create failed: ${err.message}`);
    const recheck = await github.rest.pulls.list({
      owner, repo, state: "open", base, head: `${owner}:${head}`,
    });
    if (recheck.data.length > 0) {
      await github.rest.pulls.update({ owner, repo, pull_number: recheck.data[0].number, title, body });
      core.info(`PR existed from a concurrent run; refreshed #${recheck.data[0].number}`);
      return;
    }
    throw err;
  }

  core.info(`Opened PR #${pr.number}: ${pr.html_url}`);

  try {
    await github.rest.issues.addLabels({ owner, repo, issue_number: pr.number, labels });
  } catch (err) {
    core.warning(`Could not add labels ${labels.join(", ")}: ${err.message}`);
  }
};
